INSERT IGNORE INTO recipes (id,title,instructions,minutes,source_url,source_note) VALUES
(11,'Phở bò','Bước 1: Nướng gừng và hành, rang quế cùng hoa hồi rồi ninh với nước dùng.\nBước 2: Trụng bánh phở và chuẩn bị giá, rau thơm, chanh, ớt.\nBước 3: Xếp bánh phở và thịt bò vào tô, chan nước dùng nóng rồi dùng ngay.',90,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(12,'Phở gà','Bước 1: Luộc gà với gừng và hành, hớt bọt để nước dùng trong.\nBước 2: Trụng bánh phở, rửa giá và rau thơm.\nBước 3: Xé thịt gà, xếp vào tô, chan nước dùng và dùng với chanh.',75,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(13,'Bún chả','Bước 1: Ướp thịt heo xay với hành và nước mắm, vo thành viên rồi nướng chín.\nBước 2: Pha nước mắm chua ngọt với chanh và ớt.\nBước 3: Dọn bún cùng chả nướng, giá và rau thơm.',45,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(14,'Bún bò Huế','Bước 1: Ninh thịt bò với sả, hành và gia vị để lấy nước dùng.\nBước 2: Nêm mắm ruốc và sa tế vừa khẩu vị.\nBước 3: Trụng bún, xếp thịt, chan nước dùng và thêm rau thơm.',120,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(15,'Bún riêu cua','Bước 1: Lọc cua đồng với nước, đun nhỏ lửa để tạo riêu.\nBước 2: Nấu nước dùng với cà chua và nêm nước mắm.\nBước 3: Trụng bún, múc riêu cua lên trên và dùng với rau sống.',60,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(16,'Gỏi cuốn tôm thịt','Bước 1: Luộc tôm và thịt, để nguội rồi thái mỏng.\nBước 2: Làm mềm bánh tráng, xếp bún, rau thơm, giá, tôm và thịt.\nBước 3: Cuốn chặt tay, dùng kèm nước mắm chua ngọt.',35,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(17,'Chả giò','Bước 1: Trộn thịt heo xay với cà rốt, nấm hương và hành.\nBước 2: Cuốn nhân bằng bánh tráng thành từng cuốn vừa tay.\nBước 3: Chiên lửa vừa đến khi vàng giòn, để ráo dầu.',50,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(18,'Bánh xèo','Bước 1: Pha bột gạo với nước thành hỗn hợp loãng.\nBước 2: Xào tôm, thịt và giá, sau đó đổ bột vào chảo nóng.\nBước 3: Gập bánh khi mép giòn, dùng với rau thơm và nước mắm.',40,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(19,'Bánh cuốn nhân thịt','Bước 1: Pha bột gạo với nước, chuẩn bị nhân thịt heo xay xào hành.\nBước 2: Tráng bột thật mỏng trên mặt chảo hấp.\nBước 3: Cuộn nhân vào bánh, dùng nóng với nước mắm.',55,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(20,'Cao lầu Hội An','Bước 1: Ướp thịt heo với nước mắm, hành và tỏi rồi áp chảo.\nBước 2: Trụng sợi bún, chuẩn bị rau thơm và giá.\nBước 3: Xếp bún, thịt và rau vào tô, chan ít nước sốt rồi trộn đều.',50,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(21,'Mì Quảng tôm thịt','Bước 1: Xào tôm và thịt với hành, sau đó thêm nước dùng.\nBước 2: Nêm nước mắm và đun nhỏ lửa cho thấm.\nBước 3: Trụng bún, xếp nhân, thêm rau thơm và chan ít nước dùng.',55,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(22,'Cơm tấm sườn','Bước 1: Ướp sườn với nước mắm, hành và tỏi.\nBước 2: Nướng hoặc áp chảo sườn đến khi chín vàng.\nBước 3: Nấu cơm, dọn cùng sườn và nước mắm pha.',60,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(23,'Cơm gà xối mỡ','Bước 1: Luộc gà với gừng và hành đến khi vừa chín.\nBước 2: Để gà ráo rồi chiên hoặc xối dầu nóng cho da vàng.\nBước 3: Nấu cơm, chặt gà và dùng cùng nước mắm.',70,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(24,'Cơm chiên Dương Châu','Bước 1: Nấu cơm trước, để nguội và tơi hạt.\nBước 2: Xào trứng, cà rốt, bắp và thịt với hành.\nBước 3: Cho cơm vào đảo lửa lớn, nêm nước mắm rồi tắt bếp.',30,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(25,'Cơm chiên cá mặn','Bước 1: Chiên cá basa, gỡ thịt và làm tơi.\nBước 2: Xào trứng cùng hành, cho cơm nguội vào đảo đều.\nBước 3: Trộn cá vào cơm, nêm vừa ăn và dùng nóng.',35,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(26,'Cá kho tộ','Bước 1: Ướp cá với nước mắm, hành và tiêu.\nBước 2: Thắng màu rồi xếp cá vào nồi đất.\nBước 3: Thêm nước dừa, kho nhỏ lửa đến khi nước sánh.',50,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(27,'Thịt kho trứng','Bước 1: Luộc trứng và ướp thịt với nước mắm, hành.\nBước 2: Thắng màu, cho thịt vào đảo săn.\nBước 3: Thêm nước dừa và trứng, kho nhỏ lửa đến khi mềm.',90,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(28,'Canh chua cá','Bước 1: Nấu nước với me, lọc lấy vị chua.\nBước 2: Cho cá và dứa vào nấu đến khi chín.\nBước 3: Nêm nước mắm, thêm cà chua và rau thơm rồi tắt bếp.',35,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(29,'Canh bí đỏ hầm xương','Bước 1: Chần sườn heo, rửa sạch và ninh với gừng.\nBước 2: Cho bí đỏ vào nồi khi sườn gần mềm.\nBước 3: Nêm nước mắm, nấu đến khi bí vừa chín.',55,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(30,'Canh rau ngót thịt bằm','Bước 1: Ướp thịt heo xay với hành và nước mắm.\nBước 2: Xào thịt sơ rồi thêm nước.\nBước 3: Cho rau ngót vào, nấu vừa chín và nêm lại.',25,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(31,'Canh cải chua sườn','Bước 1: Chần sườn rồi ninh với gừng đến khi mềm.\nBước 2: Rửa cải chua, cắt khúc và cho vào nồi.\nBước 3: Nêm nước mắm, đun thêm vài phút rồi dùng nóng.',60,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(32,'Canh nấm rơm đậu phụ','Bước 1: Rửa nấm rơm và cắt đậu phụ thành miếng.\nBước 2: Đun nước với gừng, cho nấm vào nấu chín.\nBước 3: Thả đậu phụ, nêm nước mắm và tắt bếp.',25,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(33,'Gà kho gừng','Bước 1: Chặt gà, ướp với gừng, hành và nước mắm.\nBước 2: Xào gà săn mặt rồi thêm ít nước.\nBước 3: Kho nhỏ lửa đến khi nước sánh và gà chín.',45,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(34,'Gà xào sả ớt','Bước 1: Ướp thịt gà với sả, ớt và nước mắm.\nBước 2: Phi tỏi, cho gà vào xào săn.\nBước 3: Thêm ít nước, đảo đến khi gà chín và thấm gia vị.',35,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(35,'Bò lúc lắc','Bước 1: Cắt thịt bò thành khối, ướp với hành và nước mắm.\nBước 2: Làm nóng chảo thật kỹ rồi áp chảo bò nhanh tay.\nBước 3: Đảo đến độ chín mong muốn, dùng ngay với rau củ.',25,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(36,'Bò xào rau muống','Bước 1: Chần rau muống và để ráo.\nBước 2: Xào thịt bò với tỏi trên lửa lớn.\nBước 3: Cho rau muống vào đảo nhanh, nêm nước mắm rồi tắt bếp.',25,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(37,'Thịt heo kho tiêu','Bước 1: Ướp thịt heo với nước mắm, hành và tiêu.\nBước 2: Xào thịt săn và thêm ít nước.\nBước 3: Kho nhỏ lửa đến khi thịt mềm, nước kho sánh.',45,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(38,'Thịt băm chưng trứng','Bước 1: Trộn thịt heo xay với trứng, hành và cà rốt.\nBước 2: Nêm nước mắm rồi cho hỗn hợp vào bát chịu nhiệt.\nBước 3: Hấp đến khi hỗn hợp đông, quét lòng đỏ và hấp thêm.',40,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(39,'Sườn xào chua ngọt','Bước 1: Chần sườn, ướp nước mắm rồi chiên hoặc áp chảo.\nBước 2: Nấu sốt me cùng nước mắm và đường.\nBước 3: Cho sườn vào đảo đến khi sốt bám đều.',50,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(40,'Tôm rang me','Bước 1: Làm sạch tôm, ướp với nước mắm và hành.\nBước 2: Rang tôm đến khi chuyển màu.\nBước 3: Thêm sốt me, đảo đến khi sánh và phủ đều tôm.',25,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(41,'Mực xào dứa','Bước 1: Làm sạch mực, chần nhanh và để ráo.\nBước 2: Xào mực với hành trên lửa lớn.\nBước 3: Thêm dứa và cà chua, nêm nước mắm rồi tắt bếp.',25,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(42,'Tôm hấp nước dừa','Bước 1: Rửa sạch tôm và xếp vào xửng.\nBước 2: Đun nước dừa trong nồi hấp.\nBước 3: Hấp tôm đến khi đỏ hồng, dùng với chanh và ớt.',20,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(43,'Đậu phụ nhồi thịt','Bước 1: Trộn thịt heo xay với hành và nước mắm.\nBước 2: Khoét nhẹ đậu phụ, nhồi nhân vào giữa.\nBước 3: Sốt đậu phụ với cà chua đến khi nhân chín.',35,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(44,'Đậu phụ kho nấm','Bước 1: Áp chảo đậu phụ đến khi vàng nhẹ.\nBước 2: Xào nấm hương và nấm rơm với hành.\nBước 3: Thêm đậu phụ, nước mắm và ít nước, kho ngấm vị.',30,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(45,'Nấm xào sả','Bước 1: Làm sạch nấm và băm sả.\nBước 2: Phi tỏi, xào sả cho thơm.\nBước 3: Cho nấm vào đảo chín, nêm nước mắm và ớt.',20,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(46,'Gỏi gà rau răm','Bước 1: Luộc gà với gừng, để nguội rồi xé sợi.\nBước 2: Trộn gà với hành, rau răm và chanh.\nBước 3: Nêm nước mắm, rắc đậu phộng nếu có và dùng ngay.',35,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(47,'Nộm dưa leo cà rốt','Bước 1: Thái dưa leo và cà rốt thành sợi, để ráo.\nBước 2: Pha nước trộn từ chanh, nước mắm và ớt.\nBước 3: Trộn rau ngay trước khi ăn để giữ độ giòn.',15,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(48,'Bánh tráng cuốn thịt heo','Bước 1: Luộc thịt heo với gừng, để nguội rồi thái lát.\nBước 2: Chuẩn bị bánh tráng, bún, dưa leo và rau thơm.\nBước 3: Cuốn các nguyên liệu, dùng cùng nước mắm.',45,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(49,'Chả lá lốt','Bước 1: Trộn thịt heo xay với hành và nước mắm.\nBước 2: Cuộn nhân trong lá lốt thành từng miếng.\nBước 3: Chiên hoặc nướng đến khi lá thơm và nhân chín.',35,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.'),
(50,'Miến gà','Bước 1: Luộc gà với gừng và hành, giữ lại nước dùng.\nBước 2: Ngâm miến mềm, xé thịt gà và chuẩn bị nấm hương.\nBước 3: Trụng miến, xếp thịt và chan nước dùng nóng.',55,'https://www.vietnam.travel/things-to-do/vietnamese-food','Biên soạn cho đồ án, tham khảo văn hóa ẩm thực Việt Nam từ Vietnam Tourism.');
